cpp_source = """
#include <hip/hip_runtime.h>

#define HS 96
#define TR 16
#define TC 64

__global__ void fused_attention_kernel(
    const float* __restrict__ Q,
    const float* __restrict__ K,
    const float* __restrict__ V,
    float* __restrict__ Y,
    int B, int nh, int T, float scale) 
{
    int b = blockIdx.x;
    int h = blockIdx.y;
    int t_tile = blockIdx.z;

    int t_start = t_tile * TR;
    int tid_x = threadIdx.x; // 0..31
    int tid_y = threadIdx.y; // 0..15

    int q_row_global = t_start + tid_y;

    // Use long long for offset to prevent overflow
    long long head_offset = (long long)(b * nh + h) * T * HS;

    const float* Q_ptr = Q + head_offset;
    const float* K_ptr = K + head_offset;
    const float* V_ptr = V + head_offset;
    float* Y_ptr = Y + head_offset;

    __shared__ float Q_sh[TR][HS];
    __shared__ float K_sh[TC][HS];
    __shared__ float V_sh[TC][HS];

    float acc[3] = {0.0f, 0.0f, 0.0f};
    float l = 0.0f;
    float m = -1e30f; 

    // Load Q
    int flat_tid = tid_y * 32 + tid_x;
    // Block size is 32 * 16 = 512
    for (int i = flat_tid; i < TR * HS; i += 512) {
        int r = i / HS;
        int c = i % HS;
        if (t_start + r < T) {
            Q_sh[r][c] = Q_ptr[(t_start + r) * HS + c];
        } else {
            Q_sh[r][c] = 0.0f;
        }
    }

    __syncthreads();

    int num_k_tiles = (T + TC - 1) / TC;

    for (int k_tile = 0; k_tile < num_k_tiles; ++k_tile) {
        int k_start = k_tile * TC;

        // Causal masking optimization
        if (k_start > t_start + TR - 1) break;

        for (int i = flat_tid; i < TC * HS; i += 512) {
            int r = i / HS;
            int c = i % HS;
            if (k_start + r < T) {
                K_sh[r][c] = K_ptr[(k_start + r) * HS + c];
                V_sh[r][c] = V_ptr[(k_start + r) * HS + c];
            } else {
                K_sh[r][c] = 0.0f;
                V_sh[r][c] = 0.0f;
            }
        }
        __syncthreads();

        if (q_row_global < T) {
            float q_val[3];
            q_val[0] = Q_sh[tid_y][tid_x];
            q_val[1] = Q_sh[tid_y][tid_x + 32];
            q_val[2] = Q_sh[tid_y][tid_x + 64];

            for (int j = 0; j < TC; ++j) {
                int k_idx_global = k_start + j;

                if (k_idx_global > q_row_global) continue; 
                if (k_idx_global >= T) continue;

                float dot = 0.0f;
                dot += q_val[0] * K_sh[j][tid_x];
                dot += q_val[1] * K_sh[j][tid_x + 32];
                dot += q_val[2] * K_sh[j][tid_x + 64];

                // Warp reduction
                for (int offset = 16; offset > 0; offset /= 2) {
                    dot += __shfl_xor(dot, offset);
                }

                dot *= scale;

                float m_prev = m;
                m = fmaxf(m, dot);

                float exp_score = expf(dot - m);
                float correction = expf(m_prev - m);

                l = l * correction + exp_score;

                acc[0] = acc[0] * correction + exp_score * V_sh[j][tid_x];
                acc[1] = acc[1] * correction + exp_score * V_sh[j][tid_x + 32];
                acc[2] = acc[2] * correction + exp_score * V_sh[j][tid_x + 64];
            }
        }
        __syncthreads();
    }

    if (q_row_global < T) {
        float inv_l = 1.0f / l;
        acc[0] *= inv_l;
        acc[1] *= inv_l;
        acc[2] *= inv_l;

        Y_ptr[q_row_global * HS + tid_x] = acc[0];
        Y_ptr[q_row_global * HS + tid_x + 32] = acc[1];
        Y_ptr[q_row_global * HS + tid_x + 64] = acc[2];
    }
}

torch::Tensor fused_attention_hip(torch::Tensor q, torch::Tensor k, torch::Tensor v, float scale) {
    auto B = q.size(0);
    auto nh = q.size(1);
    auto T = q.size(2);
    // HS is implicit 96

    auto y = torch::empty_like(q);

    dim3 grid(B, nh, (T + TR - 1) / TR);
    dim3 block(32, TR);

    fused_attention_kernel<<<grid, block>>>(
        q.data_ptr<float>(),
        k.data_ptr<float>(),
        v.data_ptr<float>(),
        y.data_ptr<float>(),
        B, nh, T, scale
    );

    return y;
}
"""

fused_attn_module = load_inline(
    name="fused_attention",
    cpp_sources=cpp_source,
    functions=["fused_attention_hip"],
    verbose=True,
    extra_cflags=['-O3', '--gpu-max-threads-per-block=1024']
)

class ModelNew(nn.Module):
    def __init__(self, n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen):
        super().__init__()
        assert n_embd % n_head == 0
        self.c_attn = nn.Linear(n_embd, 3 * n_embd)
        self.c_proj = nn.Linear(n_embd, n_embd)
        self.attn_dropout = nn.Dropout(attn_pdrop)
        self.resid_dropout = nn.Dropout(resid_pdrop)
        self.n_head = n_head
        self.n_embd = n_embd

        # We don't need the bias buffer anymore for the custom kernel

    def forward(self, x):
        B, T, C = x.size()

        # calculate query, key, values
        q, k ,v  = self.c_attn(x).split(self.n_embd, dim=2)

        # Transpose to (B, nh, T, hs) and ensure contiguous for the kernel
        # The kernel assumes packed inputs
        k = k.view(B, T, self.n_head, C // self.n_head).transpose(1, 2).contiguous()
        q = q.view(B, T, self.n_head, C // self.n_head).transpose(1, 2).contiguous()
        v = v.view(B, T, self.n_head, C // self.n_head).transpose(1, 2).contiguous()

        # Custom fused attention
        scale = 1.0 / math.sqrt(k.size(-1))
        y = fused_attn_module.fused_attention_hip(q, k, v, scale)

        # Re-assemble
        y = y.transpose(1, 2).contiguous().view(B, T, C)

        # Output projection
        y = self.resid_dropout(self.c_proj(y))
        return y

def get_inputs():
    batch_size = 128
    seq_len = 512
    n_embd = 768
    return [torch.rand(batch_size, seq_len, n_embd).cuda()]

def get_init_inputs():
    n_embd = 768
    n_head = 8
    attn_pdrop = 0.0
    resid_pdrop = 0.0
    max_seqlen = 1024
    return [n_embd, n_head, attn_pdrop, resid_pdrop, max_seqlen]

import torch
